mapper.select:
SELECT count(*) FROM homework h INNER JOIN course c ON h.course_id = c.id INNER JOIN staff_assignment sa ON h.course_id=sa.course_id WHERE sa.user_id= (select id from user where login_id = #{loginId})
AND h.title like concat('%',#{keyword},'%')
AND c.name = #{nameForLt}

SELECT count(*) FROM homework h INNER JOIN course c ON h.course_id = c.id INNER JOIN learner_enrollment le ON h.course_id=le.course_id WHERE le.user_id= (select id from user where login_id = #{loginId})
AND h.title like concat('%',#{keyword},'%')
AND c.name = #{nameForLt}

SELECT h.id, h.title, h.start_date, h.end_date, h.content, h.course_id, h.read_count, h.instructor_id, h.created_at, h.updated_at, h.deleted_at FROM homework h INNER JOIN course c ON h.course_id = c.id
AND c.is_in_progress = #{isInProgressForAdmin}
AND c.name = #{nameForAdmin}
AND h.title like concat('%',#{keyword},'%')
ORDER BY h.end_date ASC
ORDER BY h.end_date DESC
ORDER BY h.title ASC
ORDER BY h.title DESC
limit #{pagingRequest.skip},#{pagingRequest.pageSize}

SELECT count(*) FROM homework h INNER JOIN course c ON h.course_id = c.id
AND c.is_in_progress = #{isInProgressForAdmin}
AND c.name = #{nameForAdmin}
AND h.title like concat('%',#{keyword},'%')

select name from course
is_in_progress = #{isInProgressForAdmin}
order by start_date desc
